      case 'M':
        current = point();
        path.moveTo(current.dx, current.dy);
        start = current;
        command = relative ? 'l' : 'L';
      case 'L':
        current = point();
        path.lineTo(current.dx, current.dy);
      case 'H':
        current = Offset(number() + (relative ? current.dx : 0), current.dy);
        path.lineTo(current.dx, current.dy);
      case 'V':
