        final b = point(), end = point();
        path.cubicTo(a.dx, a.dy, b.dx, b.dy, end.dx, end.dy);
        current = end;
        nextCubic = b;
      case 'Q':
        final a = point(), end = point();
        path.quadraticBezierTo(a.dx, a.dy, end.dx, end.dy);
        current = end;
        nextQuadratic = a;
      case 'T':
        final a = {'Q', 'T'}.contains(previous) && quadratic != null
            ? current * 2 - quadratic
            : current;
        final end = point();
        path.quadraticBezierTo(a.dx, a.dy, end.dx, end.dy);
        current = end;
        nextQuadratic = a;
